CREATE TABLE public.integration_runtime (key text PRIMARY KEY, payload jsonb NOT NULL DEFAULT '{}'::jsonb, lock_owner uuid, lock_until timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.integration_runtime TO service_role;
REVOKE ALL ON public.integration_runtime FROM anon, authenticated;
ALTER TABLE public.integration_runtime ENABLE ROW LEVEL SECURITY;
CREATE POLICY runtime_service_only ON public.integration_runtime FOR ALL TO service_role USING (true) WITH CHECK (true);
CREATE FUNCTION public.claim_integration_lock(p_key text, p_owner uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.integration_runtime(key) VALUES (p_key) ON CONFLICT DO NOTHING; UPDATE public.integration_runtime SET lock_owner=p_owner, lock_until=now()+interval '45 seconds' WHERE key=p_key AND (lock_until IS NULL OR lock_until < now()); RETURN FOUND; END; $$;
REVOKE ALL ON FUNCTION public.claim_integration_lock(text,uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_integration_lock(text,uuid) TO service_role;
CREATE TABLE public.ebay_notification_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, subscription_id text UNIQUE NOT NULL, destination_id text NOT NULL, topic_id text NOT NULL, status text NOT NULL DEFAULT 'ENABLED', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,topic_id));
GRANT SELECT ON public.ebay_notification_subscriptions TO authenticated;
GRANT ALL ON public.ebay_notification_subscriptions TO service_role;
ALTER TABLE public.ebay_notification_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY subscriptions_owner_read ON public.ebay_notification_subscriptions FOR SELECT TO authenticated USING (auth.uid()=user_id);
CREATE POLICY subscriptions_service_only ON public.ebay_notification_subscriptions FOR ALL TO service_role USING (true) WITH CHECK (true);
CREATE TABLE public.ebay_notification_receipts (notification_id text PRIMARY KEY, subscription_id text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, status text NOT NULL DEFAULT 'pending');
GRANT ALL ON public.ebay_notification_receipts TO service_role;
REVOKE ALL ON public.ebay_notification_receipts FROM anon, authenticated;
ALTER TABLE public.ebay_notification_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY receipts_service_only ON public.ebay_notification_receipts FOR ALL TO service_role USING (true) WITH CHECK (true);
ALTER TABLE public.ebay_listings ADD COLUMN image_url text, ADD COLUMN watch_count integer NOT NULL DEFAULT 0;
ALTER TABLE public.ebay_listings DROP CONSTRAINT ebay_listings_draft_id_fkey;
ALTER TABLE public.ebay_listings ADD CONSTRAINT ebay_listings_draft_id_fkey FOREIGN KEY (draft_id) REFERENCES public.listing_drafts(id) ON DELETE SET NULL;